/*no state change by default*/

vstate = rstate;

v_cpu_res = '{0, 0}; tag_write = '{0, 0, 0}';

/*read tag by default*/

tag_req.we = '0;

/*direct map index for tag*/

tag_req.index = cpu_req.addr[13:4];

